const {

  currentMeal,
  mealType

} = $json.body;

// SAFETY

if (!currentMeal) {

  throw new Error(
    'currentMeal missing'
  );

}

// CONTEXT

const calories =
  currentMeal.calories || 400;

const title =
  currentMeal.title || '';

const description =
  currentMeal.description || '';

// PROMPT

const prompt = `

Genera una comida tipo: ${mealType} 
Con calorías objetivo: ${calories} 
Evita generar una comida similar a:
${title}
${description}

Prioriza variedad en:
- ingredientes
- proteína principal
- estilo de cocina
- preparación

Requisitos:
- Inspiración mediterránea, japonesa o longevidad
- Saludable, realista y práctica
- Ingredientes fáciles de conseguir
- Mantener calorías similares
- Mantener tono claro y simple
- Responde sólo en español

Devuelve SOLO un JSON válido.

Formato exacto:

{
  "title": "",
  "description": "",
  "calories": 0,

  "macros": {

    "protein": 0,
    "carbs": 0,
    "fat": 0

  },

  "recipe": {

    "ingredients": [],

    "steps": []

  }

}

`;

return [

  {

    json: {

      prompt

    }

  }

];

// EXTRACT RAW CONTENT

let raw = null;

// OPENAI CHAT COMPLETIONS

if ($json.choices?.[0]?.message?.content) {

  raw =
    $json.choices[0]
      .message
      .content;

}

// FALLBACKS

if (!raw) {

  raw =
    $json.output ||
    $json.text ||
    $json.response;

}

// LAST FALLBACK

if (!raw) {

  raw =
    JSON.stringify($json);

}

// EXTRACT JSON

function extractJson(txt) {

  if (
    !txt ||
    typeof txt !== 'string'
  ) {

    return null;

  }

  // REMOVE ```json fences

  const fenced = txt.match(
    /```(?:json)?\s*([\s\S]*?)```/i
  );

  if (fenced) {

    return fenced[1].trim();

  }

  // EXTRACT FIRST JSON OBJECT

  const first =
    txt.indexOf('{');

  const last =
    txt.lastIndexOf('}');

  if (
    first !== -1 &&
    last !== -1 &&
    last > first
  ) {

    return txt.slice(
      first,
      last + 1
    );

  }

  return txt.trim();

}

const candidate =
  extractJson(raw);

// PARSE JSON

let meal = null;

let error = null;

try {

  meal =
    JSON.parse(candidate);

} catch (e1) {

  try {

    const relaxed =
      candidate

        .replace(
          /\u2018|\u2019|\u201C|\u201D/g,
          '"'
        )

        .replace(
          /,(\s*[}\]])/g,
          '$1'
        );

    meal =
      JSON.parse(relaxed);

  } catch (e2) {

    error =
      e2.message;

  }

}

// VALIDATION

if (!meal || !meal.title) {

  return [{
    json: {
      success: false,
      message: "No pudimos regenerar este platillo. Inténtalo nuevamente.",
      debug: candidate
    }
  }];

}

if (!meal.recipe) {

  meal.recipe = {

    ingredients: [],

    steps: []

  };

}

if (!meal.macros) {

  meal.macros = {

    protein: 0,

    carbs: 0,

    fat: 0

  };

}

// SUCCESS

return [

  {

    json: {

      success: true,

      meal

    }

  }

];

const prefs =
  $json.preferences || {};

let prefText = "";

if (prefs.diet)
  prefText +=
    `La persona sigue una dieta ${prefs.diet}. `;

if (prefs.cuisine)
  prefText +=
    `Prefiere cocina inspirada en ${prefs.cuisine}. `;

if (
  Array.isArray(prefs.allergies)
  && prefs.allergies.length
)
  prefText +=
    `Alergias: ${prefs.allergies.join(", ")}. `;

if (
  Array.isArray(prefs.dislikes)
  && prefs.dislikes.length
)
  prefText +=
    `No consume: ${prefs.dislikes.join(", ")}. `;

const previousMeals = [];

($json.meals?.days || [])
  .forEach(day => {

    Object.values(day.meals || {})
      .forEach(meal => {

        if (meal?.title) {

          previousMeals.push(meal.title);

        }

      });

});

const system_message = `
Eres la nutricionista de Dietavity.

Diseñas planes de alimentación saludables inspirados en los hábitos alimentarios de países con alta esperanza de vida, especialmente:
- Japón
- Italia
- España
- Noruega

Los planes deben ser:
- sencillos
- prácticos
- fáciles de cocinar
- con ingredientes comunes
- con recetas familiares
- equilibrados
- variados
- lenguaje natural y neutro para Latinoamérica
- Usa los nombres de ingredientes y alimentos más ampliamente comprendidos en Latinoamérica
- Evita regionalismos muy específicos de un solo país salvo que la región de la usuaria lo indique

Reglas estrictas:
- Responde solo con un JSON válido.
- No incluyas texto fuera del objeto JSON.
- No uses comentarios, explicaciones ni emojis.
- Usa claves exactamente como se solicita.
- Usa números sin unidades.
- Cumple estrictamente con el formato pedido.
`;

const prompt = `
Genera un nuevo plan de alimentación semanal.

${prefText}

Objetivos:
- Priorizar variedad
- Evitar comidas repetitivas
- Inspirarse en hábitos de longevidad
- Mantener comidas simples y realistas

Evita repetir comidas similares a:

${previousMeals.join("\n")}

Devuelve ÚNICAMENTE JSON válido.

El JSON debe tener EXACTAMENTE esta estructura:

{
  "duration_days": 7,
  "days": [
    {
      "day": 1,
      "meals": {
        "breakfast": {},
        "lunch": {},
        "dinner": {},
        "snacks": []
      }
    }
  ]
}

Desayuno, comida y cena deben incluir:
- title
- description
- calories
- macros {
    protein,
    carbs,
    fat
  }
- recipe {
    ingredients[],
    steps[]
  }

Los snacks deben ser un arreglo de textos simples.

Ejemplo:

"snacks": [
  "1 yogur natural pequeño",
  "1 manzana con canela"
]

No agregues texto fuera del JSON.
`;

return {
  json: {
    user_id: $json.user_id,
    program_id: $json.program_id || null,
    week_id: $json.week_id || null,
    system_message,
    prompt
  }
};

