const raw =
  $('Incoming Message').item.json.data.body ?? '';

const text = raw
  .trim()
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[.!?,¡¿]+$/g, '')
  .replace(/\s+/g, ' ');

const thankYouPatterns = [

  /^grs$/,
  /^gracias$/,
  /^muchas gracias$/,
  /^mil gracias$/,
  /^gracias por todo$/,
  /^gracias por la informacion$/,
  /^gracias por la información$/,
  /^perfecto gracias$/,
  /^vale gracias$/,
  /^te lo agradezco$/,
  /^muy amable$/,
  /^excelente gracias$/,

];

const isThankYou =
  thankYouPatterns.some(pattern => pattern.test(text));

return [{
  json: {
    chatInput: raw.trim(),
    isThankYou
  }
}];

const raw =
  $('Incoming Message').item.json.data.body ?? '';

const text = raw
  .trim()
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[.!?,¡¿]+$/g, '')
  .replace(/\s+/g, ' ');

const hasQuestion =
  raw.includes('?') ||
  raw.includes('¿');

const negativePatterns = [

  /^no$/,
  /^no gracias$/,
  /^gracias pero no$/,
  /^ahora no$/,
  /^por ahora no$/,
  /^no por ahora$/,
  /^tal vez despues$/,
  /^tal vez después$/,
  /^quiz[aá] despues$/,
  /^quiz[aá] después$/,
  /^en otro momento$/,
  /^no me interesa$/,
  /^prefiero que no$/,
  /^no quiero$/,
  /^paso$/,
  /^dejemoslo asi$/,
  /^dejémoslo así$/,
  /^no,? gracias$/,

];

const isNegative =
  !hasQuestion &&
  negativePatterns.some(pattern => pattern.test(text));

return [{
  json: {
    chatInput: raw.trim(),
    isNegative
  }
}];

const generationContext = $('Build Weekly Update Prompt').first().json;

