    error: valid ? null : 'A valid user id is required.'
  }
}];

const profile = $json.profile || {};
const preferences = { ...($json.preferences || {}) };

if (profile.eating_style) preferences.diet = profile.eating_style;
if (Array.isArray(profile.allergies) && profile.allergies.length) {
  preferences.allergies = [...new Set([...(preferences.allergies || []), ...profile.allergies])];
}
if (Array.isArray(profile.foods_to_avoid) && profile.foods_to_avoid.length) {
